    "testing"
    "fmt"
)

func find_closest_elements(numbers []float64) []interface{} {
    sort.Slice(numbers, func(i, j int) bool {
        return numbers[i] < numbers[j]
    })

    minDiff := numbers[1] - numbers[0]
    closestPair := []interface{}{numbers[0], numbers[1]}

    for i := 1; i < len(numbers); i++ {
        diff := numbers[i] - numbers[i-1]
        if diff < minDiff {
            minDiff = diff
            closestPair = []interface{}{numbers[i-1], numbers[i]}
        }
    }

    return closestPair
}
