func sort_array(array []int) []int {
    if len(array) == 0 {
        return []int{}
    }

    first := array[0]
    last := array[len(array)-1]
    total := first + last

    copy := make([]int, len(array))
    for i, v := range array {
        copy[i] = v
    }

    if total % 2 == 1 {
        sort.Slice(copy, func(i, j int) bool {
            return copy[i] < copy[j]
        })
    } else {
        sort.Slice(copy, func(i, j int) bool {
            return copy[i] > copy[j]
        })
    }

    return copy
}
