func count_up_to(n int) []int {
    if n <= 2 {
        return []int{}
    }

    sieve := make([]bool, n)
    for i := 2; i < n; i++ {
        sieve[i] = true
    }

    for i := 2; i*i < n; i++ {
        if sieve[i] {
            for j := i*i; j < n; j += i {
                sieve[j] = false
            }
        }
    }

    primes := []int{}
    for i := 2; i < n; i++ {
        if sieve[i] {
            primes = append(primes, i)
        }
    }
    return primes
}
