package valid_date_test

import (
	"strings"
	"strconv"
)

func valid_date(date string) bool {
	if len(date) == 0 {
		return false
	}

	if len(date) != 10 {
		return false
	}

	parts := strings.Split(date, "-")
	if len(parts) != 3 {
		return false
	}

	if len(parts[0]) != 2 || len(parts[1]) != 2 || len(parts[2]) != 4 {
		return false
	}

	for _, p := range parts {
		for i := range p {
			if p[i] < '0' || p[i] > '9' {
				return false
			}
		}
	}

	month, err := strconv.Atoi(parts[0])
	day, err := strconv.Atoi(parts[1])
	year, err := strconv.Atoi(parts[2])
	if err != nil {
		return false
	}

	if month < 1 || month > 12 {
		return false
	}

	var maxDay int
	if month == 2 {
		if (year%4 == 0 && year%100 != 0) || year%400 == 0 {
			maxDay = 29
		} else {
			maxDay = 28
		}
	} else if month == 4 || month == 6 || month == 9 || month == 11 {
		maxDay = 30
	} else {
		maxDay = 31
	}

	if day < 1 || day > maxDay {
		return false
	}

	return true
}
