func sort_array(array []int) []int {
    if len(array) == 0 {
        return []int{}
    }

    sum := array[0] + array[len(array)-1]

    sorted := make([]int, len(array))
    copy(sorted, array)

    if sum%2 == 1 {
        sort.Slice(sorted, func(i, j int) bool { return sorted[i] < sorted[j] })
    } else {
        sort.Slice(sorted, func(i, j int) bool { return sorted[i] > sorted[j] })
    }

    return sorted
}
