fn triples_sum_to_zero(l: Vec<isize>) -> bool {
    if l.len() < 3 {
        return false;
    }

    let mut sorted = l.clone();
    sorted.sort();

    for i in 0..sorted.len() - 2 {
        let mut left = i + 1;
        let mut right = sorted.len() - 1;

        while left < right {
            let total = sorted[i] + sorted[left] + sorted[right];
            if total == 0 {
                return true;
            } else if total < 0 {
                left += 1;
            } else {
                right -= 1;
            }
        }
    }

    false
}
