fn change_base(x: isize, base: isize) -> String {
    if x == 0 {
        return "0".to_string();
    }

    let mut is_negative = x < 0;
    let mut n = if is_negative { -x } else { x };

    let mut digits = Vec::new();
    while n > 0 {
        let remainder = n % base;
        n = n / base;
        digits.push(remainder);
    }

    digits.reverse();

    let mut s = String::new();
    for digit in digits {
        s.push((digit as u8 + '0' as u8) as char);
    }

    if is_negative {
        s = format!("-{}", s);
    }

    s
}
