fn change_base(x: isize, base: isize) -> String {
    if x == 0 {
        return "0".to_string();
    }

    let sign = x < 0;
    let mut num = x.abs();
    let mut digits = Vec::new();

    while num > 0 {
        let remainder = num % base;
        num = num / base;
        digits.push(remainder);
    }

    digits.reverse();

    let mut s = String::new();
    for d in digits {
        s.push('0' + d);
    }

    if sign {
        s = format!("-{}", s);
    }

    s
}
