fn pluck(arr: Vec<isize>) -> Vec<isize> {
    if arr.is_empty() {
        return vec![];
    }

    let mut min_even = None;
    let mut min_index = None;

    for (index, &value) in arr.iter().enumerate() {
        if value % 2 == 0 {
            if min_even.is_none() {
                min_even = Some(value);
                min_index = Some(index);
            } else {
                if value < min_even.unwrap() {
                    min_even = Some(value);
                    min_index = Some(index);
                }
            }
        }
    }

    if min_even.is_none() {
        return vec![];
    }

    vec![min_even.unwrap(), min_index.unwrap() as isize]
}
```

