        return None;
    }

    let sum_mag = arr.iter().map(|x| x.abs()).sum();
    let mut product_sign = 1;
    for x in arr {
        if x == 0 {
            product_sign = 0;
        } else if x < 0 {
            product_sign *= -1;
        }
    }

    Some(sum_mag * product_sign)
}
```

