    assert_eq!(prod_signs(vec![0, 1]), Some(0));
    assert_eq!(prod_signs(vec![1, 2, 3]), Some(6));
    assert_eq!(prod_signs(vec![1, -2, 3]), Some(-6));
    assert_eq!(prod_signs(vec![2, -3, 4]), Some(-9));
}
