function triples_sum_to_zero(l: number[]): boolean {
    l.sort((a, b) => a - b);
    for (let i = 0; i < l.length - 2; i++) {
        if (i > 0 && l[i] === l[i - 1]) continue;
        let left = i + 1;
        let right = l.length - 1;
        while (left < right) {
            const sum = l[i] + l[left] + l[right];
            if (sum === 0) return true;
            else if (sum < 0) left++;
            else right--;
        }
    }
    return false;
}
