  function getDigitSum(num: number): number {
    const absNum = Math.abs(num);
    const str = absNum.toString();
    let sum = 0;
    for (const char of str) {
      sum += parseInt(char);
    }
    if (num < 0) {
      const firstDigit = parseInt(str[0]);
      return sum - 2 * firstDigit;
    }
    return sum;
  }

  let count = 0;
  for (const num of arr) {
    if (getDigitSum(num) > 0) {
      count++;
    }
  }
  return count;
}
