function change_base(x: number, base: number): string {
  if (x === 0) return "0";
  let digits = [];
  while (x > 0) {
    const remainder = x % base;
    x = Math.floor(x / base);
    digits.push(remainder);
  }
  return digits.reverse().map(String).join('');
}
