```typescript
function correct_bracketing(brackets: string): boolean {
  let count = 0;
  for (const char of brackets) {
    if (char === '<') {
      count++;
    } else if (char === '>') {
      count--;
    }
    if (count < 0) {
      return false;
    }
  }
  return count === 0;
}
```

