```typescript
function pluck(arr: number[]): number[] {
  let minEven = Infinity;
  let minIndex = -1;

  for (let i = 0; i < arr.length; i++) {
    const num = arr[i];
    if (num % 2 === 0) {
      if (num < minEven) {
        minEven = num;
        minIndex = i;
      }
    }
  }

  return minIndex === -1 ? [] : [minEven, minIndex];
}
```

