```typescript
function count_up_to(n: number): number[] {
  if (n <= 2) return [];
  const primes: number[] = [];
  for (let i = 2; i < n; i++) {
    if (isPrime(i)) {
      primes.push(i);
    }
  }
  return primes;
}

function isPrime(x: number): boolean {
  if (x < 2) return false;
  for (let i = 2; i * i <= x; i++) {
    if (x % i === 0) return false;
  }
  return true;
}
```

