```typescript
function count_nums(arr: number[]): number {
  function computeSum(n: number): number {
    const str = n.toString();
    if (str[0] === '-') {
      const digits = str.slice(1);
      let sum = 0;
      for (let i = 0; i < digits.length; i++) {
        const digit = parseInt(digits[i]);
        if (i === 0) {
          sum -= digit;
        } else {
          sum += digit;
        }
      }
      return sum;
    } else {
      let sum = 0;
      for (const char of str) {
        sum += parseInt(char);
      }
      return sum;
    }
  }

  let count = 0;
  for (const num of arr) {
    if (computeSum(num) > 0) {
      count++;
    }
  }
  return count;
}
```

