assert.deepEqual(count_nums([-1, 11, -11]), 1);
assert.deepEqual(count_nums([1, 1, 2]), 3);
assert.deepEqual(count_nums([0]), 0);
assert.deepEqual(count_nums([-12]), 1);
```

