```typescript
function simplify(x: string, n: string): boolean {
  const [num1, den1] = x.split('/');
  const [num2, den2] = n.split('/');
  const num1Int = parseInt(num1);
  const den1Int = parseInt(den1);
  const num2Int = parseInt(num2);
  const den2Int = parseInt(den2);

  const productNum = num1Int * num2Int;
  const productDen = den1Int * den2Int;

  return productNum % productDen === 0;
}
```

